import { test, expect } from "../fixtures.js";

// Runs against the production image, where the service worker exists (it is not
// generated by `npm run dev`). Chromium only: installability needs a CDP session.

// The worker installs and claims the page on the first visit; the reload makes sure the
// page under test is one it controls.
async function loadControlledPage(page) {
  await page.goto("/");
  await page.evaluate(() => navigator.serviceWorker.ready);
  await page.reload();
  await expect
    .poll(() => page.evaluate(() => !!navigator.serviceWorker.controller))
    .toBe(true);
}

const cachedPaths = (page) =>
  page.evaluate(async () => {
    const paths = [];
    for (const key of await caches.keys()) {
      const cache = await caches.open(key);
      for (const request of await cache.keys()) {
        paths.push(new URL(request.url).pathname);
      }
    }
    return paths;
  });

test(
  "the service worker controls the app and caches only the app shell",
  { tag: ["@pwa", "@smoke"] },
  async ({ page }) => {
    await loadControlledPage(page);
    await page.goto("/containers");
    await expect(page.getByText("Docker Auto-Heal Service")).toBeVisible();
    // Real API traffic has happened by now; none of it may be in Cache Storage.
    const paths = await cachedPaths(page);

    expect(paths).toContain("/index.html");
    expect(paths.some((p) => p.startsWith("/assets/"))).toBe(true);
    expect(paths.filter((p) => p.startsWith("/api/"))).toEqual([]);
  },
);

test(
  "the manifest is valid and the app is installable",
  { tag: "@pwa" },
  async ({ page }) => {
    await loadControlledPage(page);
    const cdp = await page.context().newCDPSession(page);
    const { installabilityErrors } = await cdp.send(
      "Page.getInstallabilityErrors",
    );
    const { url, errors: manifestErrors } = await cdp.send(
      "Page.getAppManifest",
    );

    expect(url).toMatch(/\/manifest\.json$/);
    expect(manifestErrors).toEqual([]);
    // Playwright contexts are incognito-like, so Chromium always adds "in-incognito";
    // any other id is a real manifest or service-worker problem.
    expect(
      installabilityErrors.filter((e) => e.errorId !== "in-incognito"),
    ).toEqual([]);
  },
);

test(
  "failed API requests fail normally instead of returning cached data or the app shell",
  { tag: ["@pwa", "@errors"] },
  async ({ page, context }) => {
    await loadControlledPage(page);
    // Prime the API once while online, so a cache that stored it would have an entry.
    const online = await page.evaluate(() =>
      fetch("/api/status").then((r) => r.status),
    );
    expect(online).toBe(200);

    await context.setOffline(true);
    try {
      const outcome = await page.evaluate(() =>
        fetch("/api/status").then(
          (r) => `response ${r.status}`,
          () => "network error",
        ),
      );
      expect(outcome).toBe("network error");
      expect(
        (await cachedPaths(page)).filter((p) => p.startsWith("/api/")),
      ).toEqual([]);
    } finally {
      await context.setOffline(false);
    }
  },
);
